"""건물 기하와 가시선 판정.

paper5 승계 자산 `models.py`의 3차원 선분 대 직육면체 교차 판정을 옮겨 왔다. 승계 구현은 2차원
투영에 Liang-Barsky 절단을 적용한 뒤 수직 범위를 따로 확인하는 방식이었는데, 이 방식은 선분이
건물의 수직 범위를 지나가되 그 구간이 2차원 투영의 교차 구간과 어긋날 때 잘못 참을 돌려준다.
여기서는 세 축을 함께 다루는 슬랩 판정으로 바꾸어 그 결함을 없앴다. 슬랩 판정은
승계 자산 `environment.py:193-216`이 이미 사용하던 방식이다.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, List, Sequence, Tuple

Point3 = Tuple[float, float, float]
Point2 = Tuple[float, float]


@dataclass
class Building:
    """도심 건물을 나타내는 축 정렬 직육면체."""

    building_id: str
    x_min: float
    x_max: float
    y_min: float
    y_max: float
    height: float
    z_min: float = 0.0

    def __post_init__(self) -> None:
        if self.x_min > self.x_max:
            self.x_min, self.x_max = self.x_max, self.x_min
        if self.y_min > self.y_max:
            self.y_min, self.y_max = self.y_max, self.y_min

    @property
    def z_max(self) -> float:
        return self.z_min + self.height

    @property
    def center_2d(self) -> Point2:
        return ((self.x_min + self.x_max) / 2.0, (self.y_min + self.y_max) / 2.0)

    @property
    def width(self) -> float:
        return self.x_max - self.x_min

    @property
    def length(self) -> float:
        return self.y_max - self.y_min

    def contains_point(self, point: Point3, margin: float = 0.0) -> bool:
        x, y, z = point
        return (
            self.x_min - margin <= x <= self.x_max + margin
            and self.y_min - margin <= y <= self.y_max + margin
            and self.z_min - margin <= z <= self.z_max + margin
        )

    def intersects_box_2d(
        self, x_min: float, x_max: float, y_min: float, y_max: float, margin: float = 0.0
    ) -> bool:
        """수평 평면에서 직사각형 두 개가 겹치는지 확인한다."""
        return (
            self.x_min - margin < x_max
            and self.x_max + margin > x_min
            and self.y_min - margin < y_max
            and self.y_max + margin > y_min
        )

    def intersects_segment_3d(self, p1: Point3, p2: Point3, margin: float = 0.0) -> bool:
        """3차원 선분이 건물 직육면체와 교차하는지 슬랩 방법으로 판정한다."""
        box_min = (self.x_min - margin, self.y_min - margin, self.z_min - margin)
        box_max = (self.x_max + margin, self.y_max + margin, self.z_max + margin)

        t_enter = 0.0
        t_exit = 1.0

        for axis in range(3):
            direction = p2[axis] - p1[axis]
            if abs(direction) < 1e-12:
                if p1[axis] < box_min[axis] or p1[axis] > box_max[axis]:
                    return False
                continue
            inv = 1.0 / direction
            t1 = (box_min[axis] - p1[axis]) * inv
            t2 = (box_max[axis] - p1[axis]) * inv
            if t1 > t2:
                t1, t2 = t2, t1
            t_enter = max(t_enter, t1)
            t_exit = min(t_exit, t2)
            if t_enter > t_exit:
                return False
        return True

    def intersects_line_2d(self, p1: Point2, p2: Point2, margin: float = 0.0) -> bool:
        """수평 투영에서 선분이 건물 밑면과 교차하는지 판정한다. 경로 계획의 우회 판단에 쓴다."""
        return self.intersects_segment_3d(
            (p1[0], p1[1], self.z_min), (p2[0], p2[1], self.z_min), margin=margin
        )

    def corners_2d(self, margin: float = 0.0) -> List[Point2]:
        return [
            (self.x_min - margin, self.y_min - margin),
            (self.x_max + margin, self.y_min - margin),
            (self.x_max + margin, self.y_max + margin),
            (self.x_min - margin, self.y_max + margin),
        ]


def is_line_of_sight_clear(
    p1: Point3, p2: Point3, buildings: Sequence[Building], margin: float = 0.0
) -> bool:
    """두 점 사이의 가시선이 건물에 막히지 않는지 확인한다."""
    for building in buildings:
        if building.intersects_segment_3d(p1, p2, margin=margin):
            return False
    return True


def blocking_buildings(
    p1: Point3, p2: Point3, buildings: Iterable[Building], margin: float = 0.0
) -> List[Building]:
    """가시선을 막는 건물 목록을 돌려준다. 진단과 시각화에 쓴다."""
    return [b for b in buildings if b.intersects_segment_3d(p1, p2, margin=margin)]

