"""관측 인터페이스.

수학 모델 2.2절의 데이터 누수 판정 규칙을 코드 구조로 강제한다. 계획 정보와 실측 정보를 서로 다른
객체로 분리하고 각각 조회 가능한 시각 범위를 다르게 두었다.

- `ScheduleOracle`: 계획 정보 조회. PSU가 사전에 배포한 4D 궤적을 읽으며 현재 시각부터 룩어헤드
  지평까지의 미래를 조회할 수 있다. 지평을 넘는 조회는 거부한다.
- `MeasurementLog`: 실측 정보 조회. 시뮬레이터가 물리 진행마다 기록한 값만 담고 있으며 현재 시각을
  넘는 조회는 거부한다. 기록되지 않은 미래 값은 애초에 존재하지 않는다.

두 객체를 하나로 합치지 않는 이유는, 합쳐 두면 어느 조회가 어느 규칙을 따르는지가 호출부의 주의에만
의존하게 되기 때문이다. 분리해 두면 실측 정보를 미래 시각으로 조회하려는 시도가 타입 수준에서
막힌다.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np

from comm_nodes import NETWORK_ORDER, NetworkType
from config_loader import section as cfg_section
from deviation import TrajectoryDeviation
from flight_phase import FlightPhase, phase_one_hot
from planned_trajectory import PlannedState, PlannedTrajectory

#: 부동소수 비교에서 현재 시각과 같은 값을 미래로 오판하지 않도록 두는 여유.
TIME_EPSILON = 1e-9


class LookaheadViolationError(RuntimeError):
    """계획 정보를 룩어헤드 지평 밖의 시각으로 조회했을 때 발생한다."""


class FutureMeasurementError(RuntimeError):
    """실측 정보를 현재 시각보다 뒤의 시각으로 조회했을 때 발생한다."""


class ScheduleOracle:
    """계획 정보 조회 창구.

    수학 모델 2.2절이 계획 정보에 허용한 시각 범위는 `t <= t_k + T_la`다. 이 객체는 현재 시각을
    들고 있으면서 그 범위를 벗어난 조회를 거부한다.
    """

    def __init__(self, planned: PlannedTrajectory, now: Optional[float] = None) -> None:
        cfg = cfg_section("DECISION")
        self._planned = planned
        self.horizon_s = float(cfg["LOOKAHEAD_HORIZON_S"])
        self.num_samples = int(cfg["LOOKAHEAD_SAMPLES"])
        if self.horizon_s <= 0.0:
            raise ValueError("룩어헤드 지평은 0보다 커야 합니다.")
        if self.num_samples <= 0:
            raise ValueError("룩어헤드 표본 수는 1 이상이어야 합니다.")
        self._now = float(now if now is not None else planned.start_time)

    @property
    def now(self) -> float:
        return self._now

    def advance_to(self, t: float) -> None:
        """현재 시각을 갱신한다. 시뮬레이터의 물리 진행만 이 함수를 호출한다."""
        value = float(t)
        if value < self._now - TIME_EPSILON:
            raise ValueError("현재 시각은 뒤로 되돌릴 수 없습니다.")
        self._now = value

    def _check(self, t: float) -> None:
        limit = self._now + self.horizon_s
        if t > limit + TIME_EPSILON:
            raise LookaheadViolationError(
                f"계획 정보 조회가 룩어헤드 지평을 넘었습니다. 요청 {t:.3f}s, 허용 상한 {limit:.3f}s"
            )

    def state_at(self, t: float) -> PlannedState:
        """지평 안의 임의 시각에 대한 계획 상태를 돌려준다."""
        self._check(float(t))
        return self._planned.state_at(float(t))

    def current_state(self) -> PlannedState:
        return self._planned.state_at(self._now)

    def phase(self) -> FlightPhase:
        """현재 비행 단계. 계획 궤적에서 결정되므로 계획 정보다."""
        return self._planned.phase_at(self._now)

    def lookahead(self) -> List[PlannedState]:
        """수학 모델 2.1절의 Λ_k에 해당하는 룩어헤드 표본을 돌려준다."""
        return self._planned.lookahead(self._now, self.horizon_s, self.num_samples)

    @property
    def required_arrival_time(self) -> float:
        return self._planned.required_arrival_time


@dataclass
class MeasurementRecord:
    """어느 시각에 실제로 관측한 값 한 벌."""

    time_s: float
    position: np.ndarray
    velocity: np.ndarray
    altitude_m: float
    deviation: TrajectoryDeviation
    link_observation: Dict[NetworkType, Dict[str, float]]
    connected_network: Optional[NetworkType]


class MeasurementLog:
    """실측 정보 조회 창구.

    시뮬레이터가 물리 진행마다 `append`로 기록을 쌓고, 에이전트는 `at`이나 `history`로 과거만
    조회한다. 기록되지 않은 시각을 요청하면 예외를 던진다.
    """

    def __init__(self) -> None:
        self._records: List[MeasurementRecord] = []
        self._times: List[float] = []

    def __len__(self) -> int:
        return len(self._records)

    @property
    def now(self) -> float:
        if not self._records:
            raise FutureMeasurementError("아직 어떤 실측도 기록되지 않았습니다.")
        return self._times[-1]

    def append(self, record: MeasurementRecord) -> None:
        if self._times and record.time_s < self._times[-1] - TIME_EPSILON:
            raise ValueError("실측 기록은 시간 순서대로만 쌓을 수 있습니다.")
        self._records.append(record)
        self._times.append(record.time_s)

    def latest(self) -> MeasurementRecord:
        if not self._records:
            raise FutureMeasurementError("아직 어떤 실측도 기록되지 않았습니다.")
        return self._records[-1]

    def at(self, t: float) -> MeasurementRecord:
