TIME_EPSILON = 1e-9


class LookaheadViolationError(RuntimeError):
    """계획 정보를 룩어헤드 지평 밖의 시각으로 조회했을 때 발생한다."""


class FutureMeasurementError(RuntimeError):
    """실측 정보를 현재 시각보다 뒤의 시각으로 조회했을 때 발생한다."""


class ScheduleOracle:
    """계획 정보 조회 창구.

    수학 모델 2.2절이 계획 정보에 허용한 시각 범위는 `t <= t_k + T_la`다. 이 객체는 현재 시각을
    들고 있으면서 그 범위를 벗어난 조회를 거부한다.
    """

    def __init__(self, planned: PlannedTrajectory, now: Optional[float] = None) -> None:
        cfg = cfg_section("DECISION")
        self._planned = planned
        self.horizon_s = float(cfg["LOOKAHEAD_HORIZON_S"])
        self.num_samples = int(cfg["LOOKAHEAD_SAMPLES"])
        if self.horizon_s <= 0.0:
            raise ValueError("룩어헤드 지평은 0보다 커야 합니다.")
        if self.num_samples <= 0:
            raise ValueError("룩어헤드 표본 수는 1 이상이어야 합니다.")
        self._now = float(now if now is not None else planned.start_time)

    @property
    def now(self) -> float:
        return self._now

    def advance_to(self, t: float) -> None:
        """현재 시각을 갱신한다. 시뮬레이터의 물리 진행만 이 함수를 호출한다."""
        value = float(t)
        if value < self._now - TIME_EPSILON:
            raise ValueError("현재 시각은 뒤로 되돌릴 수 없습니다.")
        self._now = value

    def _check(self, t: float) -> None:
        limit = self._now + self.horizon_s
        if t > limit + TIME_EPSILON:
            raise LookaheadViolationError(
                f"계획 정보 조회가 룩어헤드 지평을 넘었습니다. 요청 {t:.3f}s, 허용 상한 {limit:.3f}s"
            )

    def state_at(self, t: float) -> PlannedState:
        """지평 안의 임의 시각에 대한 계획 상태를 돌려준다."""
        self._check(float(t))
        return self._planned.state_at(float(t))

    def current_state(self) -> PlannedState:
        return self._planned.state_at(self._now)

    def phase(self) -> FlightPhase:
        """현재 비행 단계. 계획 궤적에서 결정되므로 계획 정보다."""
        return self._planned.phase_at(self._now)

    def lookahead(self) -> List[PlannedState]:
        """수학 모델 2.1절의 Λ_k에 해당하는 룩어헤드 표본을 돌려준다."""
        return self._planned.lookahead(self._now, self.horizon_s, self.num_samples)

    @property
    def required_arrival_time(self) -> float:
        return self._planned.required_arrival_time


